<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Mini Spreadsheet</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0;
      min-width: 600px;
      min-height: 400px;
      background: #f3f6fa;
      color: #172033;
      font-family: Arial, Helvetica, sans-serif;
